() => {
  const items: {
    href: string
    text: string
    'aria-current'?: 'page'
  }[] = [
    {
      href: '#',
      text: 'Item 4',
      'aria-current': 'page',
    },
    {
      href: '#',
      text: 'Item 5',
    },
    {
      href: '#',
      text: 'Item 6',
    },
    {
      href: '#',
      text: 'Item 7',
    },
    {
      href: '#',
      text: 'Item 8',
    },
    {
      href: '#',
      text: 'Item 9',
    },
  ]
  const Item = ({
    leadingVisual,
    text,
    trailingVisual,
    ...rest
  }: CustomItemProps) => {
    return (
      <NavList.Item key={text} onClick={() => {}} href="#" {...rest}>
        {leadingVisual ? (
          <NavList.LeadingVisual>
            <Octicon icon={leadingVisual} />
          </NavList.LeadingVisual>
        ) : null}
        {text}

        {trailingVisual ? (
          <NavList.TrailingVisual>
            {typeof trailingVisual === 'string' ? (
              trailingVisual
            ) : (
              <Octicon icon={trailingVisual as React.ElementType} />
            )}
            <VisuallyHidden>results</VisuallyHidden>
          </NavList.TrailingVisual>
        ) : null}
      </NavList.Item>
    )
  }
  return (
    <PageLayout>
      <PageLayout.Pane position="start">
        <NavList>
          <NavList.Item href="#">Item 1</NavList.Item>
          <NavList.Item href="#">Item 2</NavList.Item>
          <NavList.Item href="#">Item 3</NavList.Item>
          <NavList.GroupExpand
            label="Show more"
            items={items}
            renderItem={Item}
          />
        </NavList>
      </PageLayout.Pane>
      <PageLayout.Content></PageLayout.Content>
    </PageLayout>
  )
}

